new='''/** Rows read per page when walking a restored project's content. */
const WALK_PAGE_SIZE = 100;

/**
 * Index writers decide searchability themselves: a subject is indexed only
 * while it and every ancestor (issue, project) is live, and is removed — with
 * everything beneath it — otherwise.
 */
export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  if (issue.archivedAt !== null) {
    await searchRepo.deleteIssueSearchDocuments(orgId, issue.id);
    return;
  }
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project || project.archivedAt !== null) {
    await searchRepo.deleteIssueSearchDocuments(orgId, issue.id);
    return;
  }
  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\\n"),
    issue.projectId,
  );
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  const issue =
    comment.archivedAt === null
      ? await issueRepo.findIssueById(orgId, comment.issueId)
      : null;
  const project =
    issue && issue.archivedAt === null
      ? await projectRepo.findProjectById(orgId, issue.projectId)
      : null;
  if (!issue || !project || project.archivedAt !== null) {
    await searchRepo.deleteSearchDocument(orgId, "comment", comment.id);
    return;
  }
  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    issue.projectId,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  if (project.archivedAt !== null) {
    await searchRepo.deleteProjectSearchDocuments(orgId, project.id);
    return;
  }
  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\\n"),
    project.id,
  );
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  switch (subjectKind) {
    case "project":
      await searchRepo.deleteProjectSearchDocuments(
        orgId,
        subjectId as ProjectId,
      );
      return;
    case "issue":
      await searchRepo.deleteIssueSearchDocuments(orgId, subjectId);
      return;
    case "comment":
      await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
      return;
  }
}

